PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,email_verified INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS profiles(id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,username TEXT NOT NULL UNIQUE,name TEXT NOT NULL,bio TEXT NOT NULL DEFAULT '',location TEXT NOT NULL DEFAULT '',website TEXT NOT NULL DEFAULT '',avatar_url TEXT,banner_url TEXT,verified INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,aal INTEGER NOT NULL DEFAULT 1,expires_at INTEGER NOT NULL,mfa_verified_at INTEGER);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS mfa_factors(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,secret TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0,last_step INTEGER NOT NULL DEFAULT -1,friendly_name TEXT NOT NULL DEFAULT 'Authenticator');
CREATE INDEX IF NOT EXISTS mfa_user ON mfa_factors(user_id);
CREATE TABLE IF NOT EXISTS rate_limits(id TEXT PRIMARY KEY,hits INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS posts(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,content TEXT NOT NULL CHECK(length(trim(content)) BETWEEN 1 AND 280),image_url TEXT,external_platform TEXT,external_url TEXT,reply_to_id TEXT REFERENCES posts(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS posts_created ON posts(created_at DESC);
CREATE INDEX IF NOT EXISTS posts_author ON posts(author_id,created_at DESC);
CREATE INDEX IF NOT EXISTS posts_reply ON posts(reply_to_id);
CREATE TABLE IF NOT EXISTS post_likes(post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(post_id,user_id));
CREATE TABLE IF NOT EXISTS reposts(post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(post_id,user_id));
CREATE TABLE IF NOT EXISTS bookmarks(post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(post_id,user_id));
CREATE INDEX IF NOT EXISTS bookmarks_user ON bookmarks(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS follows(follower_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,following_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(follower_id,following_id),CHECK(follower_id<>following_id));
CREATE INDEX IF NOT EXISTS follows_following ON follows(following_id);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,recipient_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,actor_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,post_id TEXT REFERENCES posts(id) ON DELETE CASCADE,type TEXT NOT NULL,read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS notifications_recipient ON notifications(recipient_id,created_at DESC);
CREATE TABLE IF NOT EXISTS rooms(id TEXT PRIMARY KEY,host_id TEXT NOT NULL REFERENCES profiles(id),title TEXT NOT NULL,invite_hash TEXT NOT NULL,invite_expires INTEGER NOT NULL,ended INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS rooms_host ON rooms(host_id,created_at DESC);
CREATE TABLE IF NOT EXISTS participants(id TEXT PRIMARY KEY,room_id TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,token_hash TEXT NOT NULL,user_id TEXT REFERENCES users(id),name TEXT NOT NULL,expires_at INTEGER NOT NULL,last_seen INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS participants_room ON participants(room_id,last_seen);
CREATE TABLE IF NOT EXISTS signals(id INTEGER PRIMARY KEY AUTOINCREMENT,room_id TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,sender TEXT NOT NULL REFERENCES participants(id) ON DELETE CASCADE,recipient TEXT NOT NULL REFERENCES participants(id) ON DELETE CASCADE,payload TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS signals_recipient ON signals(recipient,id);
